class Solution{public:vector<string>removeInvalidParentheses(string s){unordered_set<string>seen;queue<string>q;q.push(s);seen.insert(s);vector<string>r;bool ok=false;while(!q.empty()){auto x=q.front();q.pop();int b=0;for(char c:x){if(c=='(')b++;else if(c==')'&&--b<0){b=-1;break;}}if(b==0){r.push_back(x);ok=true;}if(ok)continue;for(int i=0;i<x.size();i++)if(x[i]=='('||x[i]==')'){string y=x.substr(0,i)+x.substr(i+1);if(seen.insert(y).second)q.push(y);}}return r;}};
